const client=fs.readFileSync(new URL('../client.js',import.meta.url),'utf8');
const app=fs.readFileSync(new URL('../../offline/src/app.js',import.meta.url),'utf8');
const demo=()=>C.validate(JSON.parse(fs.readFileSync(new URL('../../offline/demo.json',import.meta.url))));
test('a rejected central save preserves revisions for retry and includes only changed records',async()=>{const p=demo(),calls=[],versions={};for(const kind of ['families','tasks','sources','assets','uses','exams','patterns','workshops'])for(const x of p[kind])versions[kind+':'+x.id]=1;let reject=true;const context={HortiCore:C,HortiPrint:P,console,fetch:async(url,init)=>{const payload=init.body?JSON.parse(init.body):null;if(url.endsWith('/api/project'))return Response.json({project:structuredClone(p),versions});if(url.includes('/api/assets?')){const id=new URL(url).searchParams.get('ids');return Response.json({assets:[p.assets.find(a=>a.id===id)]});}if(url.endsWith('/api/save')){calls.push(payload);if(reject)return Response.json({error:'Conflict'},{status:409});return Response.json({versions:Object.fromEntries(payload.changes.map(c=>[c.kind+':'+c.id,c.version+1]))});}throw Error('Unexpected request');},setInterval,clearInterval,setTimeout};vm.runInNewContext(client,context);const o=context.HortiOnline;const loaded=await o.load();loaded.tasks[0].title+=' edited';await assert.rejects(o.save(loaded),/Conflict/);assert.equal(calls[0].changes.length,1);assert.equal(calls[0].changes[0].version,1);reject=false;await o.save(loaded);assert.equal(calls[1].changes[0].version,1);await o.save(loaded);assert.equal(calls.length,2);});
async function ui(role='group',memoryOnly=false,{specialty='Baumschule',configure=()=>{}}={}){
 const data=demo();for(const t of data.tasks)if(L.zwischenpruefungScope(t))t.text='Aufgabe: Durchführen von Arbeiten an der Pflanze\nHier: Synthetisches Beispiel\n'+t.text;
 data.workshops=[{id:'meeting',title:'Termin',examYear:2027,meetingDate:'',specialties:[specialty]}];configure(data);
 const elements=new Map(),listeners={};for(const id of ['#app','#toast','#dialog','#project-input','#docx-input','#asset-input'])elements.set(id,{innerHTML:'',textContent:'',inert:false,addEventListener(){},classList:{add(){},remove(){}},close(){this.open=false;},showModal(){this.open=true;}});
 if(memoryOnly){elements.set('#seed',{textContent:JSON.stringify(data)});elements.set('meta[name=hortiexam-storage]',{content:'memory'});}
 const online={role,session:{specialty,meetingId:'meeting'},start:async()=>data,save:async()=>{},load:async()=>structuredClone(data),board:{meetings:[],requests:[]}};
 let timer=0,themeHtml='',themeInputs=[];const timers=new Map();
 const themes=()=>{const html=elements.get('#app').innerHTML;if(html!==themeHtml){themeHtml=html;themeInputs=[...html.matchAll(/<input[^>]*data-workflow-theme value="([^"]+)"([^>]*)>/g)].map(([,value,attrs])=>({value,checked:/\bchecked\b/.test(attrs),disabled:/\bdisabled\b/.test(attrs),handlers:{},addEventListener(name,fn){this.handlers[name]=fn;}}));}return themeInputs;};
 const sandbox={HortiMaterials:M,HortiSourceLayout:S,HortiIcons:I,HortiCatalog:B,HortiHelp:H,HortiDocx:D,HortiArchive:A,HortiPaper:W,HortiOnline:memoryOnly?null:online,HortiPlanning:L,HortiCore:C,HortiPrint:P,console,setTimeout:(fn,delay)=>{const id=++timer;timers.set(id,{fn,delay});return id;},clearTimeout:id=>timers.delete(id),confirm:()=>true,window:{addEventListener:(name,fn)=>listeners[name]=fn},document:{querySelector:q=>elements.get(q)||null,querySelectorAll:q=>q==='[data-workflow-theme]'?themes():[],addEventListener:(name,fn)=>listeners[name]=fn}};
 await vm.runInNewContext(app.replace('await initStorage();','globalThis.testUI={reloadCentral,changed,bankResults,setBankFilters:v=>bankFilters=v,getDb:()=>db};await initStorage();'),sandbox);
 return {online,sandbox,elements,themes,timers,dispatch:(name,event)=>listeners[name](event),click:async(kind,value,id)=>listeners.click({target:{closest:selector=>selector===`[data-${kind}]`?{dataset:{[kind]:value,id}}:null}})};
}
async function chooseThemes(u,ids){const all=u.themes().map(el=>el.value);for(const id of all){const el=u.themes().find(el=>el.value===id);if(el.checked===ids.includes(id))continue;el.checked=ids.includes(id);assert.equal(typeof el.handlers.change,'function','Theme change listener');el.handlers.change();C.validate(u.sandbox.testUI.getDb());}}
// Most existing editor regressions begin after the explicit theme-selection step.
async function createDraft(u,type){await u.click('action','track-new',type);await chooseThemes(u,u.themes().map(el=>el.value));await u.click('action','workflow-step','2');await u.click('action','paper-category','');}
test('group enters its AP/ZP workspace without coordinator or export actions',async()=>{const u=await ui(),html=u.elements.get('#app').innerHTML;assert.ok(html.includes('Zwischenprüfung'));assert.ok(html.includes('Abschlussprüfung'));assert.ok(html.includes('Baumschule'));assert.ok(!html.includes('data-action="backup"'));assert.ok(!html.includes('data-action="invitation"'));assert.ok(!html.includes('data-route="import"'));await u.click('route','import');assert.equal(u.elements.get('#app').innerHTML,html);});
test('central refresh makes both editor and modal inert until replacement is complete',async()=>{const u=await ui('admin');let finish;u.online.load=()=>new Promise(resolve=>finish=resolve);const p=u.sandbox.testUI.reloadCentral();assert.equal(u.elements.get('#app').inert,true);assert.equal(u.elements.get('#dialog').inert,true);const next=structuredClone(u.sandbox.testUI.getDb());next.tasks[0].title='Fresh central value';finish(next);await p;assert.equal(u.sandbox.testUI.getDb().tasks[0].title,'Fresh central value');assert.equal(u.elements.get('#app').inert,false);assert.equal(u.elements.get('#dialog').inert,false);});

test('pattern editor displays only categories for selected specialty and exam type',async()=>{const u=await ui('admin');await u.click('action','open-group','Baumschule');await u.click('action','track-pattern','AP');let html=u.elements.get('#app').innerHTML;assert.ok(html.includes('Gehölze sortieren und kennzeichnen'));assert.ok(html.includes('Ernte und Vermarktung'));assert.ok(!html.includes('data-slot-count'));assert.ok(!html.includes('Grabstätten pflegen'));assert.ok(!html.includes('Innenraumbegrünung'));await u.click('action','track-pattern','ZP');html=u.elements.get('#app').innerHTML;assert.ok(html.includes('Anzahl Vermehren von Pflanzen'));assert.ok(html.includes('Anzahl Aufbereitung'));assert.equal((html.match(/data-slot-count=/g)||[]).length,9);assert.ok(!html.includes('Anzahl Gehölze sortieren und kennzeichnen'));assert.ok(!html.includes('max="10"'));assert.ok(!html.includes('Anzahl Durchführen von Pflegemaßnahmen an Grabstätten')); });

test('regenerated invitations cannot be reused from a stale coordinator tab',()=>{const context={HortiPrint:P,HortiCore:C,location:{origin:'https://example.test',pathname:'/tool/'}};vm.runInNewContext(client,context);const o=context.HortiOnline;o.invitations.set('meeting',[{specialty:'Baumschule',token:'test-invitation'}]);o.invitationWindows.set('meeting',{generation:1,expires:Date.now()+100000});o.board.meetings=[{meeting_id:'meeting',active:1,generation:1,expires:Date.now()+100000}];assert.ok(o.link('meeting','Baumschule').endsWith('#invite=test-invitation'));o.board.meetings[0].generation=2;assert.equal(o.link('meeting','Baumschule'),null);});
function sessionHarness({saved,fail,status='approved',role='admin',blocked=false}={}){const values=new Map(saved?[['hortiexam-session-v1',JSON.stringify(saved)]]:[]),calls=[],els=new Map();for(const id of ['#app','#dialog'])els.set(id,{innerHTML:'',close(){}});const session={role,status,expires:Date.now()+60000,specialty:'Baumschule',meetingId:'meeting'};const ctx={HortiPrint:P,HortiCore:C,console,setTimeout:()=>1,clearTimeout(){},setInterval:()=>1,clearInterval(){},document:{querySelector:q=>els.get(q)||null},sessionStorage:{getItem:k=>{if(blocked)throw Error('blocked');return values.get(k)||null;},setItem:(k,v)=>{if(blocked)throw Error('blocked');values.set(k,v);},removeItem:k=>values.delete(k)},fetch:async(url,options)=>{calls.push({url,options});if(fail==='network')throw Error('Network unavailable');if(fail==='revoked')return Response.json({error:'Revoked'},{status:401});return Response.json(url.endsWith('/api/logout')?{ok:true}:session);}};vm.runInNewContext(client,ctx);return {o:ctx.HortiOnline,context:ctx,values,calls,session,els};}
test('reload restores a server-validated tab session without requesting a password or extending expiry',async()=>{const h=sessionHarness({saved:{token:'a'.repeat(64),code:'ABC123'}});assert.equal(typeof h.o.restore,'function');await h.o.restore();assert.equal(h.o.session.expires,h.session.expires);assert.equal(h.calls.length,1);assert.ok(h.calls[0].url.endsWith('/api/session'));assert.equal(h.calls[0].options.headers.Authorization,'Bearer '+'a'.repeat(64));assert.equal(h.o.role,'admin');});
test('revoked stored sessions are cleared before any project request',async()=>{const h=sessionHarness({saved:{token:'a'.repeat(64)},fail:'revoked'});assert.equal(typeof h.o.restore,'function');await h.o.restore();assert.equal(h.values.size,0);assert.ok(h.els.get('#app').innerHTML.includes('Zugang beendet'));assert.ok(!h.calls.some(c=>c.url.endsWith('/api/project')));});
test('network failure preserves resumable session but never loads data; blocked storage falls back to login',async()=>{const h=sessionHarness({saved:{token:'a'.repeat(64)},fail:'network'});assert.equal(typeof h.o.restore,'function');await assert.rejects(h.o.restore(),/Network/);assert.equal(h.values.size,1);assert.equal(h.calls.length,1);const blocked=sessionHarness({blocked:true});assert.equal(await blocked.o.restore(),null);assert.equal(blocked.calls.length,0);});
test('pending group reload retains pending status and logout clears tab credentials even without network',async()=>{const h=sessionHarness({saved:{token:'b'.repeat(64),code:'ABC123'},role:'group',status:'pending'});assert.equal(typeof h.o.restore,'function');await h.o.restore();assert.equal(h.o.session.status,'pending');await h.o.logout();assert.equal(h.values.size,0);const broken=sessionHarness({saved:{token:'c'.repeat(64)},fail:'network'});await assert.rejects(broken.o.restore());await assert.rejects(broken.o.logout());assert.equal(broken.values.size,0);});
test('global archive filters do not silently filter a different specialty editor',async()=>{const u=await ui('admin');await u.click('route','catalog');u.sandbox.testUI.setBankFilters({kind:'practical',source:'demo-source-0',tag:'Inventur'});await u.click('action','choose-type','ZP');await u.click('action','choose-specialty','Garten- und Landschaftsbau');await u.click('route','bank');assert.equal(u.sandbox.testUI.bankResults().length,1);await u.click('route','catalog');assert.equal(u.sandbox.testUI.bankResults().length,1);assert.equal(u.sandbox.testUI.bankResults()[0].id,'demo-task-0');});
test('group can reach help and editable paper but cannot invoke question-bank exports',async()=>{const u=await ui();const d=u.sandbox.testUI.getDb(),t=d.tasks.find(t=>t.specialty==='Baumschule'&&t.examType==='ZP');const e=C.newExam({specialty:t.specialty,examType:t.examType,examYear:2027,workshopId:'meeting'});C.addItem(e,t);d.exams.push(e);await u.click('action','select-exam',e.id);let html=u.elements.get('#app').innerHTML;assert.ok(html.includes('paper-sheet'));assert.ok(html.includes('contenteditable="plaintext-only"'));assert.ok(!html.includes('data-action="export-exam"'));await u.click('action','bank-export');assert.equal(u.elements.get('#dialog').innerHTML,'');const before=u.elements.get('#app').innerHTML;await u.click('route','help');assert.equal(u.elements.get('#app').innerHTML,before);assert.equal(u.elements.get('#dialog').open,true);assert.ok(u.elements.get('#dialog').innerHTML.includes('Cloudflare D1'));assert.ok(u.elements.get('#dialog').innerHTML.includes('Bildschirmaufnahmen'));await u.click('action','close');assert.equal(u.elements.get('#dialog').open,false);assert.equal(u.elements.get('#app').innerHTML,before);});
test('dropping a task on a paper target inserts at that position and refuses duplicate families or foreign scopes',async()=>{const u=await ui('admin'),d=u.sandbox.testUI.getDb();const t=d.tasks[0],other=structuredClone(t);other.id='another-task';other.familyId='demo-family-2';d.tasks.push(other);const e=C.newExam({specialty:t.specialty,examType:t.examType,examYear:2027,workshopId:'meeting'});C.addItem(e,t);d.exams.push(e);await u.click('action','select-exam',e.id);const drop=id=>u.dispatch('drop',{target:{closest:()=>({dataset:{paperBefore:e.items[0].id},classList:{remove(){}}})},preventDefault(){},dataTransfer:{getData:()=> 'task:'+id}});drop(other.id);assert.deepEqual(e.items.map(i=>i.originTaskId),[other.id,t.id]);drop(t.id);assert.equal(e.items.length,2);drop('demo-task-2');assert.equal(e.items.length,2);});
test('start resumes an approved stored session and loads the workspace without rendering the login form',async()=>{const h=sessionHarness({saved:{token:'d'.repeat(64)}});const p=demo();h.o.load=async()=>p;h.o.access=async()=>({meetings:[],requests:[]});h.context.location={hash:'',pathname:'/tool/',search:''};h.context.history={replaceState(){}};h.context.URLSearchParams=URLSearchParams;const result=await h.o.start();assert.equal(result.projectId,p.projectId);assert.ok(!h.els.get('#app').innerHTML.includes('login-form'));assert.equal(h.calls.length,1);});
test('preview waits for its candidate attachments and does not emit an incomplete document',async()=>{const u=await ui('admin'),d=u.sandbox.testUI.getDb(),t=d.tasks[0];d.assets.push({id:'slow-plan',name:'Plan.png',mime:'image/png',data:''});t.assetLinks.push({assetId:'slow-plan',audience:'candidate'});const e=C.newExam({specialty:t.specialty,examType:t.examType,examYear:2027,workshopId:'meeting'});C.addItem(e,t);d.exams.push(e);await u.click('action','select-exam',e.id);let finish,requested;u.online.ensureAssets=(p,ids)=>{requested=ids;return new Promise(resolve=>finish=()=>{p.assets.find(a=>a.id==='slow-plan').data='YWJj';resolve();});};u.elements.get('#dialog').showModal=()=>{};u.elements.set('#print-preview',{srcdoc:''});const opening=u.click('action','preview-candidate');await new Promise(r=>setImmediate(r));assert.ok(requested.includes('slow-plan'));assert.equal(u.elements.get('#print-preview').srcdoc,'');finish();await opening;assert.ok(u.elements.get('#print-preview').srcdoc.includes('base64,YWJj'));});
