function taskFormValues(u,t,{area='',reason='',title=t.title}={}){
 const fields={title,text:t.text,fr:t.specialty,type:t.examType,kind:t.kind,family:t.familyId,category:t.category,tags:t.tags.join(', '),qualification:t.qualification||'',points:t.points==null?'':String(t.points),minutes:t.minutes==null?'':String(t.minutes),solution:t.solution,'solution-status':t.solution?'draft':'missing',review:'review',reviewer:'',flags:t.flags.join('\n'),area,'area-reason':reason};
 for(const [key,value]of Object.entries(fields))u.elements.set('#task-'+key,{value});
 for(const [n,c]of t.criteria.entries()){u.elements.set(`[data-criterion-text="${n}"]`,{value:c.text});u.elements.set(`[data-criterion-answer="${n}"]`,{value:c.answer});u.elements.set(`[data-criterion-points="${n}"]`,{value:c.points==null?'':String(c.points)});}
 for(const [n,a]of t.assetLinks.entries()){u.elements.set(`[data-asset-audience="${n}"]`,{value:a.audience});u.elements.set(`[data-asset-caption="${n}"]`,{value:a.caption||''});}
 u.sandbox.document.querySelectorAll=q=>q==='[data-planning-category]:checked'?(t.planningCategories||[...u.elements.get('#dialog').innerHTML.matchAll(/data-planning-category value="([^"]+)" checked/g)].map(m=>m[1])).map(value=>({value})):[];
}
