test('central settings create, rename and hide themes, autosave, and leave existing exam snapshots unchanged after reload',async()=>{
 const u=await ui('admin'),d=u.sandbox.testUI.getDb(),saved=[];u.online.save=async project=>saved.push(structuredClone(project));const autosave=async()=>{const pending=[...u.timers].filter(([,x])=>x.delay===700);assert.equal(pending.length,1,'One debounced autosave');const [id,timer]=pending[0];u.timers.delete(id);await timer.fn();C.validate(u.sandbox.testUI.getDb());};
 const fields=(label,order)=>{for(const [key,value]of Object.entries({label,help:'Synthetische Erklärung',order:String(order),topics:'Synthetisches Beispiel'}))u.elements.set('#setting-category-'+key,{value});};
 await u.click('route','settings');assert.match(u.elements.get('#app').innerHTML,/Alle Gärtner-Fachrichtungen/);await u.click('action','settings-category','');fields('Synthetisches eigenes Thema',20);await u.click('action','settings-category-save','');let record=L.settingsFor(d,{examType:'ZP',specialty:'Baumschule'});assert.ok(record,u.elements.get('#toast').textContent);const custom=record.categories.find(x=>x.label==='Synthetisches eigenes Thema');assert.ok(custom);C.validate(d);
 await u.click('action','settings-category','plantwork');fields('Synthetisch benanntes Pflanzenthema',2);await u.click('action','settings-category-save','plantwork');u.elements.set('#settings-title',{value:'Synthetische {pruefungsart} {jahr}'});u.elements.set('#settings-notes',{value:'Synthetischer Hinweis für {fachrichtung}.'});u.elements.set('#settings-minutes',{value:'80'});await u.click('action','settings-save-defaults');await autosave();assert.equal(saved.length,1);assert.equal(saved[0].settings[0].revision,3);
 await u.click('action','open-group','Baumschule');await createDraft(u,'ZP');const old=d.exams.at(-1),oldBefore=JSON.stringify(old);assert.equal(old.title,'Synthetische Zwischenprüfung 2027');assert.equal(old.notes,'Synthetischer Hinweis für Baumschule.');assert.ok(old.pattern.categoryDefinitions.some(x=>x.id===custom.id&&!x.hidden));assert.equal(old.pattern.categoryDefinitions.find(x=>x.id==='plantwork').label,'Synthetisch benanntes Pflanzenthema');
 await u.click('route','settings');await u.click('action','settings-remove','plantwork');await u.click('action','settings-remove',custom.id);record=L.settingsFor(d,{examType:'ZP',specialty:'Obstbau'});assert.ok(record.categories.find(x=>x.id===custom.id)?.hidden,'Referenced custom theme is retained and hidden');assert.ok(record.categories.find(x=>x.id==='plantwork').hidden);assert.equal(JSON.stringify(old),oldBefore);await autosave();assert.equal(saved.length,2);u.online.load=async()=>structuredClone(saved.at(-1));await u.sandbox.testUI.reloadCentral();let reloaded=u.sandbox.testUI.getDb();assert.equal(JSON.stringify(reloaded.exams.find(x=>x.id===old.id)),oldBefore);
 await u.click('action','open-group','Baumschule');await u.click('action','track-new','ZP');assert.ok(!u.themes().some(x=>x.value==='plantwork'||x.value===custom.id));reloaded=u.sandbox.testUI.getDb();assert.equal(JSON.stringify(reloaded.exams.find(x=>x.id===old.id)),oldBefore);C.validate(reloaded);
});

